class Solution:
    def distributeCandies(self, candyType: list[int]) -> int:
        ordered = sorted(candyType)
        types = sum(i == 0 or value != ordered[i - 1] for i, value in enumerate(ordered))
        return min(types, len(ordered) // 2)
